SELECT 'gongkao', '牛吃草问题', 'kp-xc-quantity-math-operation-grass-eating', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "牛吃草问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "牛吃草问题本质是追及问题的变形，核心是草在同时生长，解题关键是求出草的生长速度和原有草量。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "基本模型：原有草量M，草每天生长r，每头牛每天吃1份草"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：M = (N - r) × T，其中N为牛的数量，T为吃完天数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "两组条件列方程：M = (N1-r)×T1 = (N2-r)×T2，解出r和M"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "草生长速度 r = (N1×T1 - N2×T2)/(T1 - T2)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "变形题型：窗口售票（人排队）、自动扶梯、水管注水等都可用牛吃草模型"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设每头牛每天吃草量为1份，统一单位"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "用两组条件列方程组，先求草的生长速度r，再求原有草量M"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求\"几头牛几天吃完\"：N = M/T + r"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "变形识别：看到\"同时进同时出\"类问题，联想牛吃草模型"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略草在生长，直接用原有草量除以牛数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "两组条件列方程时搞混N和T的对应关系"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "变形题不会转化：如窗口售票问题不知道类比牛吃草"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "牛吃草问题公式固定，属于\"背公式就能做对\"的题型。重点练习标准型和变形应用。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-牛吃草问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "牛吃草问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_grass_eating", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
